package net.officefloor.hq.app;

import net.officefloor.web.ObjectResponse;

/**
 * {@code GET /api/dashboard} — the home-screen summary across all three entities: the count of
 * clients, the count of projects, and the outstanding total (the sum of every SENT invoice's
 * amount, i.e. the money actually owed — drafts and paid invoices are excluded). Wired by
 * {@code officefloor/rest/api/dashboard.GET.yml}.
 */
public class DashboardGet {

    public void service(ClientRepository clients, ProjectRepository projects,
            InvoiceRepository invoices, ObjectResponse<DashboardView> response) {
        response.send(new DashboardView(clients.count(), projects.count(),
                invoices.sumSentAmount()));
    }
}
package net.officefloor.hq.app;

import java.math.BigDecimal;

/**
 * What {@code GET /api/dashboard} returns: the whole-app summary the home screen shows — how many
 * clients and projects exist, and how much money is still owed (the sum of every SENT invoice's
 * amount — drafts and paid invoices excluded). A read-only aggregate joined in {@link DashboardGet};
 * no entity of its own.
 */
public class DashboardView {

    private final long clientsCount;
    private final long projectsCount;
    private final BigDecimal outstandingTotal;

    public DashboardView(long clientsCount, long projectsCount, BigDecimal outstandingTotal) {
        this.clientsCount = clientsCount;
        this.projectsCount = projectsCount;
        this.outstandingTotal = outstandingTotal;
    }

    public long getClientsCount() {
        return clientsCount;
    }

    public long getProjectsCount() {
        return projectsCount;
    }

    public BigDecimal getOutstandingTotal() {
        return outstandingTotal;
    }
}
